INSERT INTO detection_rules (id, name, description, enabled, thresholds, created_at, updated_at) VALUES
('d0000000-0000-0000-0000-000000000001', 'Circular Fund Routing (Ring Pattern)', 'Detects closed circular payment loops where funds return to the originating entity within a short time horizon', true, '{"min_hops": 3, "max_hops": 6, "retention_time_hours": 72, "amount_retention_pct": 85}'::jsonb, '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00'),
('d0000000-0000-0000-0000-000000000002', 'Structuring & Smurfing (Threshold Evasion)', 'Identifies multiple transactions initiated just below mandatory regulatory reporting thresholds', true, '{"reporting_threshold": 1000000, "lower_bound": 900000, "upper_bound": 995000, "window_hours": 48, "min_count": 3}'::jsonb, '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00'),
('d0000000-0000-0000-0000-000000000003', 'Rapid Velocity Flow-Through', 'Flags accounts that disburse greater than 90% of incoming funds within 2 hours of receipt', true, '{"velocity_hours": 2, "disbursement_pct": 90, "min_amount": 500000}'::jsonb, '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00'),
('d0000000-0000-0000-0000-000000000004', 'Dormant Account Reactivation Spike', 'Detects sudden high-value movements from accounts dormant for over 90 consecutive days', true, '{"dormancy_days": 90, "spike_amount": 1000000}'::jsonb, '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00'),
('d0000000-0000-0000-0000-000000000005', 'Multi-Hop Layering Chain', 'Identifies linear fund transit chains traversing 4 or more intermediary accounts with minimal retention', true, '{"min_chain_hops": 4, "max_hop_delay_hours": 24, "minimum_chain_amount": 2000000}'::jsonb, '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00'),
('d0000000-0000-0000-0000-000000000006', 'Shared Intermediary (Fan-In Fan-Out Mule)', 'Detects aggregator accounts that rapidly consolidate funds from multiple disparate sources and fan out to destination accounts', true, '{"fan_in_sources_min": 4, "fan_out_dest_min": 3, "window_hours": 36}'::jsonb, '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00'),
('d0000000-0000-0000-0000-000000000007', 'High-Frequency Split Transfers', 'Flags single accounts dispersing funds into multiple sub-transfers to distinct counterparties within 60 minutes', false, '{"split_count_min": 4, "burst_window_minutes": 60, "min_aggregate_amount": 3000000}'::jsonb, '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00')
